draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // pen
  ctx.beginPath();
  ctx.rect(W/2 - 20, H/2 - 10 + 10*Math.sin(t), 10, 20);
  ctx.stroke();
  ctx.fill();

  // words
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('WORDS', W/2, H/2 + 50 + 10*Math.cos(t));

  // power
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 20, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fill();
  ctx.fillStyle = 'black';
  ctx.font = '15px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('!', W/2 + 50, H/2 - 20);

  // writing
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 80);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '15px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('^', W/2, H/2 + 80);

  ctx.restore();
}
